@@ -23,4 +23,22 @@
 <section class="card"><div class="card-head"><span class="label">Your foundlings</span><span class="label" id="partyCount">0 / 5</span></div><div class="party-list" id="party"><div class="empty-party">Your journey starts solo.</div></div></section>
 <section class="card"><div class="card-head"><span class="label">Field techniques</span><span class="label">1–3</span></div><div class="move-list" id="moves"></div></section>
 <section class="card log-card"><div class="card-head" style="margin:0"><span class="label">Trail notes</span><span class="label">LIVE</span></div><div class="log-list" id="log"></div></section></aside></div></main>
 <script>
+const $=id=>document.getElementById(id), canvas=$('scene'),ctx=canvas.getContext('2d');
+const TYPES={BLOOM:{color:'#78a97b',dark:'#3e7055',light:'#b2d88c',accent:'#f2d077',icon:'❀',moves:['Leaf Flick','Spore Puff','Vine Snap']},EMBER:{color:'#e88959',dark:'#a74e42',light:'#f6b76d',accent:'#ffe5a0',icon:'✹',moves:['Cinder Pop','Spark Bite','Flare Rush']},TIDE:{color:'#70a9b5',dark:'#3e6e81',light:'#a5d6ce',accent:'#e9f1d0',icon:'◈',moves:['Bubble Jab','Mist Veil','Tidal Skip']},DUSK:{color:'#997eb2',dark:'#594a7b',light:'#c2a8d0',accent:'#f6d894',icon:'☾',moves:['Gloom Glint','Night Pounce','Echo Cry']}};
+const SPECIES=[['Mossling','BLOOM','🌿'],['Cindercub','EMBER','🦊'],['Puddlefin','TIDE','🐟'],['Glimmercat','DUSK','🐈'],['Thornib','BLOOM','🦔'],['Sootwing','EMBER','🦉'],['Pebblit','TIDE','🪨'],['Moonmoth','DUSK','🦋'],['Bramblet','BLOOM','🍃'],['Flickerkit','EMBER','🐾'],['Driftfin','TIDE','🫧'],['Duskmite','DUSK','✨']];
+const ZONES=['FERNGLADE','CINDER HOLLOW','TIDEMOSS REACH','TWILIGHT WOOD','THE HEARTSHARD'];
+const MOVES=[['Leaf Flick','BLOOM',7],['Spore Puff','BLOOM',10],['Vine Snap','BLOOM',13],['Cinder Pop','EMBER',8],['Spark Bite','EMBER',11],['Flare Rush','EMBER',14],['Bubble Jab','TIDE',7],['Mist Veil','TIDE',9],['Tidal Skip','TIDE',13],['Gloom Glint','DUSK',8],['Night Pounce','DUSK',11],['Echo Cry','DUSK',14]];
+let G={};let cw=0,ch=0,dpr=1,lastFrame=0,toastTimer=0;
+function rng(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
+function fit(){const r=canvas.parentElement.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);cw=r.width;ch=r.height;canvas.width=Math.floor(cw*dpr);canvas.height=Math.floor(ch*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw()};window.addEventListener('resize',fit);
+function note(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
+function log(msg){G.logs.unshift(msg);G.logs=G.logs.slice(0,3);$('log').innerHTML=G.logs.map(x=>`<div class="log-line">${x}</div>`).join('')}
+function startRun(){let seed=Math.floor(Math.random()*999999);G={seed,r:rng(seed),floor:1,run:(G.run||0)+1,x:5,y:7,player:{hp:36,max:36,level:1,xp:0},party:[],wins:0,shards:0,enemies:[],battle:null,active:false,ended:false,logs:[],shake:0,step:0};generateFloor();$('seed').textContent=String(seed).padStart(6,'0');$('runLabel').textContent=`RUN ${String(G.run).padStart(2,'0')}`;$('startOverlay').style.display='none';$('endOverlay').classList.remove('show');$('encounter').classList.remove('open');$('zoneName').textContent=ZONES[0];$('depth').textContent='FLOOR 01 / 05';log('A new path takes shape beneath your feet.');log('Every victory adds a wild friend to your team.');updateUI();draw()}
+function pickSpecies(){let pool=SPECIES.filter(s=>TYPES[s[1]]);return pool[Math.floor(G.r()*pool.length)]}
+function generateFloor(){G.enemies=[];G.obstacles=[];let count=G.floor===5?1:3+G.floor;let taken=new Set(['5,7','5,6','5,5']);for(let i=0;i<14;i++){let x=Math.floor(G.r()*11),y=Math.floor(G.r()*9);if((x<2||x>8||y<1||y>7)&&G.r()<.35)continue;let key=x+','+y;if(!taken.has(key)){taken.add(key);G.obstacles.push({x,y,type:G.r()<.55?'fern':'stone',variant:Math.floor(G.r()*3)})}}
+for(let i=0;i<count;i++){let x,y,tries=0;do{x=1+Math.floor(G.r()*9);y=Math.floor(G.r()*6);tries++}while((taken.has(x+','+y)||Math.abs(x-G.x)+Math.abs(y-G.y)<3)&&tries<100);taken.add(x+','+y);let spec=G.floor===5?['Shard Warden','DUSK','🌙']:pickSpecies();let level=Math.max(1,G.floor+Math.floor(G.r()*2)-1);let hp=G.floor===5?52+level*3:15+level*5+Math.floor(G.r()*8);G.enemies.push({id:i,name:spec[0],type:spec[1],emoji:spec[2],x,y,hp,max:hp,level,alive:true,boss:G.floor===5})}
+G.exit={x:5,y:8};$('zoneName').textContent=ZONES[G.floor-1];$('depth').textContent=`FLOOR ${String(G.floor).padStart(2,'0')} / 05`;$('objective').textContent=G.floor===5?'DEFEAT THE SHARD WARDEN':`${G.enemies.length} WILD CREATURES REMAIN`}
+function levelUp(){while(G.player.xp>=G.player.level*24){G.player.xp-=G.player.level*24;G.player.level++;G.player.max+=5;G.player.hp=Math.min(G.player.max,G.player.hp+13);G.shards++;note(`LEVEL UP! You reached level ${G.player.level}`);log(`Level up! Vitality increased; found a shard.`)}}
+function updateUI(){let p=G.player;$('playerHpText').textContent=`${p.hp} / ${p.max}`;$('playerHp').style.width=`${p.hp/p.max*100}%`;$('playerHp').style.background=p.hp/p.max<.28?'#cf755e':'#6ba97c';$('rank').textContent=`FIELD SCOUT · LV ${p.level}`;$('xpText').textContent=`${p.xp} / ${p.level*24}`;$('xp').style.width=`${p.xp/(p.level*24)*100}%`;$('shards').textContent=G.shards;$('wins').textContent=G.wins;$('partyCount').textContent=`${G.party.length} / 5`;$('party').innerHTML=G.party.length?G.party.map((c,i)=>`<div class="party-row"><div class="party-icon">${c.emoji}</div><div class="party-copy"><div class="party-name">${c.name}</div><div class="party-meta">LV ${c.level} · ${c.type.toLowerCase()} friend</div></div><div class="type-tag">${c.type}</div></div>`).join(''):'<div class="empty-party">Your journey starts solo.</div>';$('objective').textContent=G.floor===5?'DEFEAT THE SHARD WARDEN':`${G.enemies.filter(e=>e.alive).length} WILD CREATURES REMAIN`;updateMoves()}
+function updateMoves(){const moves=[['Leaf Flick','BLOOM',7],['Cinder Pop','EMBER',8],['Bubble Jab','TIDE',7]];$('moves').innerHTML=moves.map((m,i)=>`<button class="move-btn ${G.selected===i?'selected':''}" data-move="${i}"><span class="move-icon">${TYPES[m[1]].icon}</span><span class="move-text"><span class="move-name">${m[0]}</span><br><span class="move-type">${m[1]}</span></span><span class="move-key">${i+1}</span></button>`).join('');document.querySelectorAll('.move-btn').forEach(b=>b.onclick=()=>{G.selected=+b.dataset.move;updateMoves();attack()})}

